}
pub fn default_fields() -> Vec<Field> {
    vec![Field::Date, Field::Status, Field::Ref, Field::Path]
}

fn match_field_at(lower: &str) -> Option<(bool, Field, usize)> {
    // bool indicates is_all (true for "all"/"a")
