    if lower.starts_with("status") {
        return Some((false, Field::Status, 6));
    }
    if lower.starts_with("date") {
        return Some((false, Field::Date, 4));
    }
    if lower.starts_with("time") {
        return Some((false, Field::Time, 4));
    }
    if lower.starts_with("path") {
        return Some((false, Field::Path, 4));
    }
    if lower.starts_with("all") {
        return Some((true, Field::Date, 3)); // dummy field, len 3, is_all true
