    if lower.starts_with("ref") {
        return Some((false, Field::Ref, 3));
    }
    if lower.starts_with("ip") {
        return Some((false, Field::Ip, 2));
    }
    let c = lower.chars().next()?;
    match c {
        'a' => Some((true, Field::Date, 1)),
        'd' => Some((false, Field::Date, 1)),
        't' => Some((false, Field::Time, 1)),
        'm' => Some((false, Field::Method, 1)),
        's' => Some((false, Field::Status, 1)),
        'i' => Some((false, Field::Ip, 1)),
        'r' => Some((false, Field::Ref, 1)),
        'p' => Some((false, Field::Path, 1)),
        _ => None,
    }
