        .arg(Arg::new("status").short('s').long("status").value_name("STATUS"))
        .arg(Arg::new("time").short('t').long("time").value_name("TIME"))
        .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
        .arg(Arg::new("no-name-check").long("no-name-check").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").default_value("tables"))
