fn format_bytes(n: u64) -> String {
    if n < 10000 {
        return format!("{}", n);
    } else if n < 999500 {
        let k = ((n as f64) / 1000.0).round() as u64;
        return format!("{}K", k);
    } else if n < 999500000 {
        if n < 10000000 {
            let v = (n as f64) / 1e6;
            return format!("{:.1}M", v);
        } else {
            let k = ((n as f64) / 1e6).round() as u64;
            return format!("{}M", k);
        }
    } else if n < 999500000000 {
        if n < 10000000000 {
            let v = (n as f64) / 1e9;
            return format!("{:.1}G", v);
        } else {
            let k = ((n as f64) / 1e9).round() as u64;
            return format!("{}G", k);
        }
    } else {
        if n < 10000000000000 {
            let v = (n as f64) / 1e12;
            return format!("{:.1}T", v);
        } else {
            let k = ((n as f64) / 1e12).round() as u64;
            return format!("{}T", k);
        }
    }
}

