fn date_to_timestamp(y: i32, m: u32, d: u32, hh: u32, mm: u32, ss: u32) -> i64 {
    // Simple days since 1970 (ignoring leap seconds, but handling leap years)
    // Use chrono if available? Use manual.
    // For sorting/filtering, relative order matters, not absolute. Use days calculation.
    let mut days: i64 = 0;
    // This is approximate but monotonic for our range (2020-2030). Use chrono NaiveDate for accuracy.
    // Use chrono crate
    use chrono::NaiveDate;
    if let Some(date) = NaiveDate::from_ymd_opt(y, m, d) {
        if let Some(dt) = date.and_hms_opt(hh, mm, ss) {
            return dt.and_utc().timestamp();
        }
    }
    // Fallback
    ((y as i64)*372 + (m as i64)*31 + (d as i64))*86400 + (hh as i64)*3600 + (mm as i64)*60 + (ss as i64)
}

fn parse_request(req: &str) -> (String, String) {
    // Implements logic inferred:
