    //   - if req=="" or req=="-" or single token without space or leading space? Then method="none" (as observed for "GET" alone, "FOO" alone, "" , " ", etc.)
    //   - else (contains space, no leading space, not "-" etc.): method candidate first token, if in known then that, else "other"
    // Check: "FOO /bar" (two tokens, unknown) => method "other" (as observed for "- /hello" => other, "FOO /bar" => other). Good.
    //   - What about "GET /bar" => GET. Good.
    //   - What about "\tGET /h" (leading tab, contains space, no leading space)? Then method "other" (as observed). Good (since candidate "\tGET" not in known => other). Good.
    // Implement exactly.
    const KNOWN: &[&str] = &["GET","HEAD","POST","PUT","DELETE","CONNECT","OPTIONS","TRACE","PATCH"];
    if req.is_empty() || req == "-" || req.starts_with(' ') || !req.contains(' ') {
        let path = if req.contains(' ') {
            // split on ' ' literal, second token
            let parts: Vec<&str> = req.split(' ').collect();
            if parts.len() >= 2 { parts[1].to_string() } else { req.to_string() }
        } else {
            req.to_string()
        };
        return ("none".to_string(), path);
    } else {
        // contains space, no leading space, not "-" etc.
        let parts: Vec<&str> = req.split(' ').collect();
        let cand = parts[0];
        let path = if parts.len() >= 2 { parts[1].to_string() } else { "".to_string() };
        if KNOWN.contains(&cand) {
            return (cand.to_string(), path);
        } else {
            return ("other".to_string(), path);
        }
