use fields::{Field, canonical_order, default_fields, parse_fields};

const VERSION: &str = "2.0.4";
static HELP_NONE: &[u8] = include_bytes!("help_none.raw");
static HELP_DUMB: &[u8] = include_bytes!("help_dumb.raw");
static HELP_40: &[u8] = include_bytes!("help_40.raw");

fn print_help() {
    let term_is_unset = std::env::var("TERM").is_err();
    if term_is_unset {
        let _ = std::io::Write::write_all(&mut std::io::stdout(), HELP_NONE);
    } else {
        if let Ok(cols) = std::env::var("COLUMNS") {
            if cols == "40" {
                let _ = std::io::Write::write_all(&mut std::io::stdout(), HELP_40);
                return;
            }
        }
        let _ = std::io::Write::write_all(&mut std::io::stdout(), HELP_DUMB);
    }
}

fn build_cli() -> Command {
    Command::new("rhit")
        .bin_name("executable")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(Arg::new("help").long("help").action(ArgAction::SetTrue))
        .arg(Arg::new("version").long("version").action(ArgAction::SetTrue))
        .arg(Arg::new("color").long("color").value_name("color").value_parser(["auto","yes","no"]).default_value("auto"))
        .arg(Arg::new("key").short('k').long("key").value_name("KEY").default_value("hits"))
        .arg(Arg::new("length").short('l').long("length").value_name("LENGTH").default_value("1"))
        .arg(Arg::new("fields").short('f').long("fields").value_name("FIELDS").default_value("date,status,ref,path"))
        .arg(Arg::new("changes").short('c').long("changes").action(ArgAction::SetTrue))
        .arg(Arg::new("date").short('d').long("date").value_name("DATE"))
        .arg(Arg::new("ip").short('i').long("ip").value_name("IP"))
        .arg(Arg::new("method").short('m').long("method").value_name("METHOD"))
        .arg(Arg::new("path").short('p').long("path").value_name("PATH"))
        .arg(Arg::new("referer").short('r').long("referer").value_name("REFERER"))
        .arg(Arg::new("status").short('s').long("status").value_name("STATUS"))
        .arg(Arg::new("time").short('t').long("time").value_name("TIME"))
        .arg(Arg::new("all").short('a').long("all").action(ArgAction::SetTrue))
        .arg(Arg::new("no-name-check").long("no-name-check").action(ArgAction::SetTrue))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").default_value("tables"))
        .arg(Arg::new("silent-load").long("silent-load").action(ArgAction::SetTrue))
        .arg(Arg::new("FILES").num_args(0..).value_name("FILES"))
}

fn parse_key(s: &str) -> Option<Key> {
    match s.to_lowercase().as_str() {
        "h" | "hit" | "hits" => Some(Key::Hits),
        "b" | "byte" | "bytes" => Some(Key::Bytes),
        _ => None,
    }
}
#[derive(Clone, Copy, PartialEq)]
enum Key { Hits, Bytes }
fn parse_output(s: &str) -> Option<Output> {
    match s.to_lowercase().as_str() {
        "t" | "tables" => Some(Output::Tables),
        "r" | "raw" => Some(Output::Raw),
        "c" | "csv" => Some(Output::Csv),
        "j" | "json" => Some(Output::Json),
        _ => None,
    }
}
#[derive(Clone, Copy, PartialEq)]
enum Output { Tables, Raw, Csv, Json }

fn main() {
    let cmd = build_cli();
    let m = match cmd.try_get_matches() {
        Ok(m) => m,
        Err(e) => { e.print().unwrap(); std::process::exit(e.exit_code()); }
    };
    let key_str: String = m.get_one::<String>("key").unwrap().clone();
    if parse_key(&key_str).is_none() {
        eprintln!("error: invalid value '{}' for '--key <KEY>': unrecognized key {:?}", key_str, key_str);
        std::process::exit(2);
    }
    let length_str: String = m.get_one::<String>("length").unwrap().clone();
    if length_str.parse::<usize>().is_err() {
        let inner = length_str.parse::<usize>().unwrap_err().to_string();
        eprintln!("error: invalid value '{}' for '--length <LENGTH>': {}", length_str, inner);
        std::process::exit(2);
    }
    let fields_str: String = m.get_one::<String>("fields").unwrap().clone();
    if let Err(c) = parse_fields(&fields_str).map(|_| ()) {
        eprintln!("error: invalid value '{}' for '--fields <FIELDS>': unrecognized field start '{}'", fields_str, c);
        std::process::exit(2);
    }
    let output_str: String = m.get_one::<String>("output").unwrap().clone();
    if parse_output(&output_str).is_none() {
        eprintln!("error: invalid value '{}' for '--output <OUTPUT>': unrecognized output {:?}", output_str, output_str);
        std::process::exit(2);
    }
    if m.get_flag("version") {
        println!("rhit {}", VERSION);
        return;
    }
    if m.get_flag("help") {
        print_help();
        return;
    }
    if let Err(e) = run(m) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}

