    if headers.is_empty() { return; }
    let ncols = headers.len();
    // Compute widths as max of header display width and data display widths (using char count, not byte len, for unicode? For ascii, same. For block chars like █ (3 bytes, 1 char), need char count. Use .chars().count())
    let mut widths = vec![0usize; ncols];
    for (i, h) in headers.iter().enumerate() {
        widths[i] = h.chars().count();
    }
    for row in rows {
        for (i, cell) in row.iter().enumerate() {
            let l = cell.chars().count();
            if l > widths[i] { widths[i] = l; }
        }
    }
    // Helper to pad cell to width with alignment
    fn pad(s: &str, width: usize, align: Align) -> String {
        let len = s.chars().count();
        if len >= width { return s.to_string(); }
        let diff = width - len;
        match align {
            Align::Left => format!("{}{}", s, " ".repeat(diff)),
            Align::Right => format!("{}{}", " ".repeat(diff), s),
            Align::Center => {
                let left = diff / 2;
                let right = diff - left;
                format!("{}{}{}", " ".repeat(left), s, " ".repeat(right))
            }
        }
    }
    // Top border: ┌ + ─*width for each col + ┬ between + ┐
    let mut top = String::from("┌");
    for (i, w) in widths.iter().enumerate() {
        top.push_str(&"─".repeat(*w));
        if i + 1 < ncols { top.push('┬'); } else { top.push('┐'); }
    }
    println!("{}", top);
    // Header row: │ + padded header for each col + │
    let mut hr = String::from("│");
    for (i, h) in headers.iter().enumerate() {
        // Headers centered
        hr.push_str(&pad(h, widths[i], Align::Center));
        hr.push('│');
    }
    println!("{}", hr);
    // Separator: ├ + ─ + ┼ + ┤
    let mut sep = String::from("├");
    for (i, w) in widths.iter().enumerate() {
        sep.push_str(&"─".repeat(*w));
        if i + 1 < ncols { sep.push('┼'); } else { sep.push('┤'); }
    }
    println!("{}", sep);
    // Data rows
    for row in rows {
        let mut line = String::from("│");
        for (i, cell) in row.iter().enumerate() {
            line.push_str(&pad(cell, widths[i], aligns[i]));
            line.push('│');
        }
        println!("{}", line);
    }
    // Bottom: └ + ─ + ┴ + ┘
    let mut bot = String::from("└");
    for (i, w) in widths.iter().enumerate() {
        bot.push_str(&"─".repeat(*w));
        if i + 1 < ncols { bot.push('┴'); } else { bot.push('┘'); }
    }
    println!("{}", bot);
}
'''
