fn print_method_table(hits: &[Hit], key: Key, _len: usize) {
    use std::collections::{HashMap, BTreeMap};
    // Compute total distinct dates (for days decision)
    let mut all_dates: Vec<(i32,u32,u32)> = hits.iter().map(|h| (h.year,h.month,h.day)).collect();
    all_dates.sort(); all_dates.dedup();
    let use_days = all_dates.len() >= 4;
    let mut map: HashMap<String, (u64,u64, HashMap<(i32,u32,u32), (u64,u64)>)> = HashMap::new();
    // Actually need per-value per-day hits/bytes for days histograms
    // Simplify: map method -> (total_hits, total_bytes, per_day map)
    let mut map2: HashMap<String, (u64,u64)> = HashMap::new();
    let mut per_day: HashMap<String, HashMap<(i32,u32,u32), (u64,u64)>> = HashMap::new();
    for h in hits {
        let e = map2.entry(h.method.clone()).or_insert((0,0));
        e.0 += 1; e.1 += h.bytes;
        let dmap = per_day.entry(h.method.clone()).or_insert(HashMap::new());
        let de = dmap.entry((h.year,h.month,h.day)).or_insert((0,0));
        de.0 += 1; de.1 += h.bytes;
    }
    let total = hits.len() as u64;
    let mut vec: Vec<(String,u64,u64)> = map2.into_iter().map(|(k,(h,b))| (k,h,b)).collect();
    vec.sort_by(|a,b| {
        let ord = if key == Key::Hits { b.1.cmp(&a.1) } else { b.2.cmp(&a.2) };
        if ord != std::cmp::Ordering::Equal { return ord; }
        let ord2 = if key == Key::Hits { b.2.cmp(&a.2) } else { b.1.cmp(&a.1) };
        if ord2 != std::cmp::Ordering::Equal { return ord2; }
        a.0.cmp(&b.0)
    });
    if !use_days {
        println!("{} methods. ", vec.len());
        if vec.is_empty() {
            let headers = vec![" # ".to_string(), "method".to_string(), "hits".to_string(), " % ".to_string(), "bytes".to_string()];
            print_table(&headers, &[], vec![Align::Right, Align::Left, Align::Right, Align::Center, Align::Right]);
            return;
        }
        let mut rows: Vec<Vec<String>> = Vec::new();
        for (idx, (method, h, b)) in vec.iter().enumerate() {
            let pct = format_percent(*h, total);
            rows.push(vec![format!("{}", idx+1), method.clone(), format!("{}", h), pct, format_bytes(*b)]);
        }
        let headers = vec![" # ".to_string(), "method".to_string(), "hits".to_string(), " % ".to_string(), "bytes".to_string()];
        print_table(&headers, &rows, vec![Align::Right, Align::Left, Align::Right, Align::Center, Align::Right]);
    } else {
        println!("methods");
        if vec.is_empty() {
            let headers = vec!["method".to_string(), "hits".to_string(), "%".to_string(), "bytes".to_string(), "days".to_string(), "trend".to_string()];
            print_table(&headers, &[], vec![Align::Center, Align::Right, Align::Center, Align::Right, Align::Left, Align::Left]);
            return;
        }
        let mut rows: Vec<Vec<String>> = Vec::new();
        for (method, h, b) in vec.iter() {
            let pct = format_percent(*h, total);
            // days histogram
            let dmap = per_day.get(method).unwrap();
            let days_str = make_days(dmap, &all_dates, key);
            rows.push(vec![method.clone(), format!("{}", h), pct, format_bytes(*b), days_str, "".to_string()]);
        }
        let headers = vec!["method".to_string(), "hits".to_string(), "%".to_string(), "bytes".to_string(), "days".to_string(), "trend".to_string()];
        print_table(&headers, &rows, vec![Align::Left, Align::Right, Align::Center, Align::Right, Align::Left, Align::Left]);
    }
}
fn make_days(per_day: &std::collections::HashMap<(i32,u32,u32), (u64,u64)>, all_dates: &[(i32,u32,u32)], key: Key) -> String {
    // One char per date, scaled per value (max for that value)
    let vals: Vec<u64> = all_dates.iter().map(|d| {
        if let Some((h,b)) = per_day.get(d) {
            if key == Key::Hits { *h } else { *b }
        } else { 0 }
    }).collect();
    let max = *vals.iter().max().unwrap_or(&0);
    if max == 0 {
        return " ".repeat(all_dates.len());
    }
    let blocks = [" ", "▁", "▂", "▃", "▄", "▅", "▆", "▇"];
    let mut s = String::new();
    for v in vals {
        if v == 0 {
            s.push(' ');
        } else {
            let level = ((v as f64) / (max as f64) * 7.0).round() as usize;
            let level = level.clamp(1, 7);
            s.push_str(blocks[level]);
        }
    }
    s
}
