fn print_status_table(hits: &[Hit], key: Key, length: usize) {
    use std::collections::{HashMap, BTreeMap};
    if length == 0 {
        let total = hits.len() as u64;
        let mut c2=0u64; let mut c3=0u64; let mut c4=0u64; let mut c5=0u64;
        for h in hits {
            let c = h.status / 100;
            if c==2 { c2+=1; } else if c==3 { c3+=1; } else if c==4 { c4+=1; } else if c==5 { c5+=1; }
        }
        println!("HTTP status codes:");
        let headers = vec!["2xx".to_string(), "3xx".to_string(), "4xx".to_string(), "5xx".to_string()];
        let rows = vec![vec![format_percent(c2,total), format_percent(c3,total), format_percent(c4,total), format_percent(c5,total)]];
        print_table(&headers, &rows, vec![Align::Center, Align::Center, Align::Center, Align::Center]);
        return;
    }
    let mut all_dates: Vec<(i32,u32,u32)> = hits.iter().map(|h| (h.year,h.month,h.day)).collect();
    all_dates.sort(); all_dates.dedup();
    let use_days = all_dates.len() >= 4;
    let mut map: HashMap<u32, (u64,u64)> = HashMap::new();
    let mut per_day: HashMap<u32, HashMap<(i32,u32,u32), (u64,u64)>> = HashMap::new();
    for h in hits {
        let e = map.entry(h.status).or_insert((0,0));
        e.0 += 1; e.1 += h.bytes;
        let dmap = per_day.entry(h.status).or_insert(HashMap::new());
        let de = dmap.entry((h.year,h.month,h.day)).or_insert((0,0));
        de.0 += 1; de.1 += h.bytes;
    }
    let total = hits.len() as u64;
    let total_distinct = map.len();
    let mut vec: Vec<(u32,u64,u64)> = map.into_iter().map(|(k,(h,b))| (k,h,b)).collect();
    {
