        let e = map.entry(h.path.clone()).or_insert((0,0));
        e.0 += 1; e.1 += h.bytes;
        let dmap = per_day.entry(h.path.clone()).or_insert(HashMap::new());
        let de = dmap.entry((h.year,h.month,h.day)).or_insert((0,0));
        de.0 += 1; de.1 += h.bytes;
    }
    let total = hits.len() as u64;
    let total_distinct = map.len();
    let mut vec: Vec<(String,u64,u64)> = map.into_iter().map(|(k,(h,b))| (k,h,b)).collect();
    {
        let mut first_seen: HashMap<String, usize> = HashMap::new();
        for (idx, h) in hits.iter().enumerate() {
            if !show_all && is_resource(&h.path) { continue; }
            first_seen.entry(h.path.clone()).or_insert(idx);
        }
        vec.sort_by(|a,b| {
            let ord = if key == Key::Hits { b.1.cmp(&a.1) } else { b.2.cmp(&a.2) };
            if ord != std::cmp::Ordering::Equal { return ord; }
            first_seen.get(&a.0).unwrap().cmp(first_seen.get(&b.0).unwrap())
        });
    }
    let max_show = if length == 0 { 10 } else { 50*length };
    let shown = std::cmp::min(vec.len(), max_show);
    let truncated = vec.len() > shown;
    vec.truncate(shown);
    if !use_days {
        if show_all {
            if truncated {
                println!("{} paths. {} most frequent:", total_distinct, shown);
            } else {
                if total_distinct == 0 {
                    println!("0 paths. ");
                } else {
                    println!("{} paths. ", total_distinct);
                }
            }
        } else {
            if truncated {
                println!("{} paths (excluding resources like images, css, \netc.). {} most frequent:", total_distinct, shown);
            } else {
                if total_distinct == 0 {
                    println!("0 paths (excluding resources like images, css, \netc.). ");
                } else {
                    println!("{} paths (excluding resources like images, css, \netc.). ", total_distinct);
                }
            }
        }
        if vec.is_empty() {
            let headers = vec![" # ".to_string(), "path".to_string(), "hits".to_string(), " % ".to_string(), "bytes".to_string()];
            print_table(&headers, &[], vec![Align::Right, Align::Left, Align::Right, Align::Center, Align::Right]);
            return;
        }
        let mut rows: Vec<Vec<String>> = Vec::new();
        for (idx, (p, h, b)) in vec.iter().enumerate() {
            let pct = format_percent(*h, total);
            rows.push(vec![format!("{}", idx+1), p.clone(), format!("{}", h), pct, format_bytes(*b)]);
        }
        let headers = vec![" # ".to_string(), "path".to_string(), "hits".to_string(), " % ".to_string(), "bytes".to_string()];
        print_table(&headers, &rows, vec![Align::Right, Align::Left, Align::Right, Align::Center, Align::Right]);
    } else {
        if show_all {
            if truncated {
                println!("{} paths. {} most frequent:", total_distinct, shown);
            } else {
                if total_distinct == 0 {
                    println!("0 paths");
                } else {
                    println!("{} paths", total_distinct);
                }
            }
        } else {
            if truncated {
                println!("{} paths (excluding resources like images, css, \netc.). {} most frequent:", total_distinct, shown);
            } else {
                if total_distinct == 0 {
                    println!("0 paths (excluding resources like images, css, \netc.)");
                } else {
                    println!("{} paths (excluding resources like images, css, \netc.)", total_distinct);
                }
            }
        }
        if vec.is_empty() {
            let headers = vec!["#".to_string(), "path".to_string(), "hits".to_string(), "bytes".to_string(), "days".to_string(), "trend".to_string()];
            print_table(&headers, &[], vec![Align::Center, Align::Left, Align::Right, Align::Right, Align::Left, Align::Left]);
            return;
        }
        let mut rows: Vec<Vec<String>> = Vec::new();
        for (idx, (p, h, b)) in vec.iter().enumerate() {
            let dmap = per_day.get(p).unwrap();
            let days_str = make_days(dmap, &all_dates, key);
            rows.push(vec![format!("{}", idx+1), p.clone(), format!("{}", h), format_bytes(*b), days_str, "".to_string()]);
        }
        let headers = vec!["#".to_string(), "path".to_string(), "hits".to_string(), "bytes".to_string(), "days".to_string(), "trend".to_string()];
        print_table(&headers, &rows, vec![Align::Center, Align::Left, Align::Right, Align::Right, Align::Left, Align::Left]);
