import subprocess, re
def run_new(*a):
    import subprocess as sp
    p=sp.run(['./target/debug/rhit']+list(a), capture_output=True, text=True, timeout=10)
    return p
def run_orig(*a):
    import subprocess as sp
    p=sp.run(['./executable']+list(a), capture_output=True, text=True, timeout=10)
    return p
def strip(s):
    return re.sub(r'\x1b\[[0-9;]*m','',s or '')
for f in ['method','status','ip','ref','path','date','time']:
    po=run_orig('--color','no','--silent-load','/tmp/rhit-test/filter.log','-f',f)
