    print(f, "match?", strip(po.stdout)==strip(pn.stdout))
    if strip(po.stdout)!=strip(pn.stdout):
        a=strip(po.stdout).splitlines()
        b=strip(pn.stdout).splitlines()
        for i,(x,y) in enumerate(zip(a,b)):
            if x!=y:
                print(f" line {i} orig {repr(x)}")
                print(f" line {i} new  {repr(y)}")
                break
        if len(a)!=len(b):
            print(f"len orig {len(a)} new {len(b)}")
