# Write status matching function to file, then integrate
import pathlib
code = r'''
fn status_matches(status: u32, pat: &str) -> bool {
    // Split by commas, separate positives and negated
    // Positives OR, negated AND (must all hold: positives ORed, then AND NOT negated)
    // Actually logic: (OR of positives) AND (AND of NOT negated)
    // If no positives (all negated), then OR part is true (all), so just AND of NOT negated
    let parts: Vec<&str> = pat.split(',').collect();
    let mut positives: Vec<String> = Vec::new();
    let mut negatives: Vec<String> = Vec::new();
    for part in parts {
        let t = part.trim();
        if t.starts_with('!') {
            negatives.push(t[1..].trim().to_string());
        } else {
            positives.push(t.to_string());
        }
    }
    // Check positives: if any positive matches, positives_ok=true, else if no positives, positives_ok=true (since all negated case, positives vacuously true? Actually for all negated, positives empty => true)
    let positives_ok = if positives.is_empty() {
        true
    } else {
        positives.iter().any(|p| status_part_matches(status, p))
    };
    if !positives_ok {
        return false;
    }
    // Check negatives: all must NOT match (i.e., status must not match any negated part)
    for n in negatives {
        if status_part_matches(status, &n) {
            return false;
        }
    }
    true
}
fn status_part_matches(status: u32, part: &str) -> bool {
    // part is trimmed, without '!' (already stripped), could be number, range, or class
    // Number: digits only, e.g., "404"
    // Range: "num-num", e.g., "200-300"
    // Class: "2xx","3xx","4xx","5xx" (single digit 2-5 + "xx")
    if part.contains('-') {
        let sp: Vec<&str> = part.split('-').collect();
        if sp.len() != 2 { return false; } // Shouldn't happen (validated)
        let a: u32 = sp[0].trim().parse().unwrap_or(99999);
        let b: u32 = sp[1].trim().parse().unwrap_or(99999);
        return a <= status && status <= b;
    } else if part.ends_with("xx") {
        if part.len() != 3 { return false; }
        let c = part.chars().next().unwrap();
        let cls = match c {
            '2' => 2, '3' => 3, '4' => 4, '5' => 5,
            _ => return false,
        };
        return status / 100 == cls;
    } else {
        if let Ok(n) = part.parse::<u32>() {
            return status == n;
        }
        return false;
    }
}
